    codeSnippets: { react: `export const InlineEditCell = ({ value, onSave }) => { const [editing, setEditing] = React.useState(false); const [draft, setDraft] = React.useState(value); const commit = () => { onSave(draft); setEditing(false); }; return editing ? <input autoFocus value={draft} onChange={e => setDraft(e.target.value)} onBlur={commit} onKeyDown={e => { if (e.key === 'Enter') commit(); if (e.key === 'Escape') { setDraft(value); setEditing(false); } }} className="w-full px-2 py-1 border-2 border-blue-500 rounded outline-none text-sm" /> : <div onDoubleClick={() => setEditing(true)} className="px-2 py-1.5 text-sm cursor-text hover:bg-blue-50 rounded min-h-8 flex items-center">{value}</div>; };` }
