    codeSnippets: { react: `export const RippleButton = ({ children, className = '' }) => { const [ripples, setRipples] = React.useState<{x:number;y:number;id:number}[]>([]); const addRipple = (e: React.MouseEvent<HTMLButtonElement>) => { const rect = e.currentTarget.getBoundingClientRect(); const id = Date.now(); setRipples(r => [...r, { x: e.clientX - rect.left, y: e.clientY - rect.top, id }]); setTimeout(() => setRipples(r => r.filter(rp => rp.id !== id)), 600); }; return <button onClick={addRipple} className={\`relative overflow-hidden \${className}\`}>{children}{ripples.map(r => <span key={r.id} style={{ left: r.x, top: r.y, transform: 'translate(-50%,-50%)' }} className="absolute w-0 h-0 bg-white/30 rounded-full animate-[ripple_0.6s_ease-out_forwards] pointer-events-none" />)}</button>; };` }
