    codeSnippets: { react: `export const OnboardingChecklist = ({ steps }) => { const completed = steps.filter(s => s.done).length; const pct = Math.round((completed / steps.length) * 100); return <div className="border rounded-2xl p-6 bg-white max-w-xl"><div className="flex items-center justify-between mb-2"><h3 className="font-bold">?쒖옉?섍린</h3><span className="text-sm text-gray-500">{completed}/{steps.length} ?꾨즺</span></div><div className="w-full bg-gray-100 rounded-full h-2 mb-5"><div style={{ width: \`\${pct}%\` }} className="bg-blue-600 h-2 rounded-full transition-all" /></div><div className="space-y-3">{steps.map((step, i) => <div key={i} className={\`flex items-center gap-4 p-3 rounded-xl \${step.done ? 'bg-green-50' : 'bg-gray-50'}\`}><div className={\`w-6 h-6 rounded-full flex items-center justify-center flex-shrink-0 text-xs font-bold \${step.done ? 'bg-green-500 text-white' : 'bg-gray-200 text-gray-500'}\`}>{step.done ? '?? : i + 1}</div><div className="flex-1"><p className={\`text-sm font-medium \${step.done ? 'line-through text-gray-400' : ''}\`}>{step.title}</p></div>{!step.done && <button className="text-xs px-3 py-1.5 bg-blue-600 text-white rounded-lg font-semibold">{step.cta}</button>}</div>)}</div></div>; };` }
