    codeSnippets: { react: `export const PageProgressBar = ({ loading }: { loading: boolean }) => { const [width, setWidth] = React.useState(0); React.useEffect(() => { if (loading) { setWidth(0); const t = setInterval(() => setWidth(w => Math.min(w + Math.random() * 15, 90)), 200); return () => clearInterval(t); } else { setWidth(100); const t = setTimeout(() => setWidth(0), 400); return () => clearTimeout(t); } }, [loading]); return <div className="fixed top-0 left-0 right-0 z-[9999] h-0.5 pointer-events-none"><div style={{ width: \`\${width}%\`, opacity: width > 0 ? 1 : 0 }} className="h-full bg-blue-600 transition-all duration-200 shadow-sm shadow-blue-500" /></div>; };` }
