    codeSnippets: { react: `export const BiometricPrompt = ({ type = 'fingerprint', onSuccess, onCancel }: { type?: 'fingerprint' | 'face'; onSuccess: () => void; onCancel: () => void }) => { const [status, setStatus] = React.useState<'idle'|'scanning'|'success'|'fail'>('idle'); const scan = () => { setStatus('scanning'); setTimeout(() => { setStatus('success'); setTimeout(onSuccess, 800); }, 1500); }; return <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50"><div className="bg-white rounded-3xl p-8 w-80 text-center"><p className="font-bold text-lg mb-2">?몄쬆 ?꾩슂</p><p className="text-sm text-gray-500 mb-8">寃곗젣瑜??꾨즺?섎젮硫??앹껜?몄쬆???꾩슂?⑸땲??/p><div onClick={scan} className={\`relative w-24 h-24 mx-auto mb-8 cursor-pointer \${status === 'scanning' ? 'animate-pulse' : ''}\`}><div className={\`absolute inset-0 rounded-full \${status === 'success' ? 'bg-green-100' : status === 'fail' ? 'bg-red-100' : 'bg-blue-50'}\`} /><div className="absolute inset-0 flex items-center justify-center text-5xl">{status === 'success' ? '?? : status === 'fail' ? '?? : type === 'fingerprint' ? '?몘' : '?お'}</div>{status === 'scanning' && <div className="absolute inset-0 rounded-full border-2 border-blue-500 animate-ping" />}</div><button onClick={onCancel} className="text-sm text-gray-400">痍⑥냼</button></div></div>; };` }
