    codeSnippets: { react: `export const FlashSaleCountdown = ({ endTime }: { endTime: Date }) => { const [timeLeft, setTimeLeft] = React.useState({ h: 0, m: 0, s: 0 }); React.useEffect(() => { const tick = () => { const diff = Math.max(0, endTime.getTime() - Date.now()); setTimeLeft({ h: Math.floor(diff / 3600000), m: Math.floor((diff % 3600000) / 60000), s: Math.floor((diff % 60000) / 1000) }); }; tick(); const id = setInterval(tick, 1000); return () => clearInterval(id); }, [endTime]); const pad = (n: number) => String(n).padStart(2, '0'); const expired = timeLeft.h === 0 && timeLeft.m === 0 && timeLeft.s === 0; return <div className={\`flex items-center gap-3 px-4 py-3 rounded-2xl \${expired ? 'bg-gray-300' : 'bg-red-500'} text-white\`}><span className="text-sm font-bold">??{expired ? '?먮ℓ醫낅즺' : '?쒖젙?밴?'}</span>{!expired && <div className="flex gap-1 font-mono font-black text-lg">{[pad(timeLeft.h), pad(timeLeft.m), pad(timeLeft.s)].map((t, i) => <><span key={i} className="bg-red-700 px-2 py-0.5 rounded-lg">{t}</span>{i < 2 && <span>:</span>}</>)}</div>}</div>; };` }
