    codeSnippets: { react: `export const AppRatingPrompt = ({ onDismiss, onReview }: { onDismiss: () => void; onReview: () => void }) => { const [stars, setStars] = React.useState(0); const [hovered, setHovered] = React.useState(0); const submitted = stars > 0; return <div className="bg-white rounded-3xl p-6 shadow-2xl max-w-xs w-full text-center mx-auto"><p className="text-2xl mb-2">狩?/p><h3 className="font-extrabold text-lg mb-1">?깆씠 留덉쓬???쒖떆?섏슂?</h3><p className="text-xs text-gray-500 mb-5">?붿쭅???됯?媛 ???꾩????⑸땲??/p><div className="flex justify-center gap-2 mb-5">{[1,2,3,4,5].map(s => <button key={s} onClick={() => setStars(s)} onMouseEnter={() => setHovered(s)} onMouseLeave={() => setHovered(0)} className="text-3xl transition-transform hover:scale-125">{(hovered || stars) >= s ? '狩? : '??}</button>)}</div>{submitted && <div className="space-y-2">{stars >= 4 ? <button onClick={onReview} className="w-full py-2.5 bg-blue-600 text-white font-bold rounded-xl text-sm">?ㅽ넗?댁뿉 由щ럭 ?④린湲?/button> : <textarea placeholder="媛쒖꽑???먯쓣 ?뚮젮二쇱꽭?? className="w-full p-3 border rounded-xl text-sm resize-none h-20 outline-none focus:ring-2 focus:ring-blue-500" />}<button onClick={onDismiss} className="w-full py-2 text-xs text-gray-400">?섏쨷??/button></div>}</div>; };` }
