    codeSnippets: { react: `export const OnboardingCarousel = ({ slides, onComplete }: { slides: {icon: string; title: string; desc: string}[]; onComplete: () => void }) => { const [page, setPage] = React.useState(0); const isLast = page === slides.length - 1; const s = slides[page]; return <div className="flex flex-col items-center justify-between h-screen bg-white px-8 py-12"><button onClick={onComplete} className="self-end text-xs text-gray-400 font-semibold">嫄대꼫?곌린</button><div className="flex-1 flex flex-col items-center justify-center text-center gap-4"><div className="text-7xl mb-4">{s.icon}</div><h2 className="text-2xl font-extrabold text-gray-900">{s.title}</h2><p className="text-sm text-gray-500 leading-relaxed max-w-xs">{s.desc}</p></div><div className="space-y-6 w-full"><div className="flex justify-center gap-2">{slides.map((_,i) => <div key={i} className={\`h-2 rounded-full transition-all \${i === page ? 'w-6 bg-blue-600' : 'w-2 bg-gray-200'}\`} />)}</div>{isLast ? <button onClick={onComplete} className="w-full py-4 bg-blue-600 text-white font-extrabold rounded-2xl text-base">?쒖옉?섍린 ??/button> : <button onClick={() => setPage(p => p+1)} className="w-full py-4 bg-blue-600 text-white font-extrabold rounded-2xl text-base">?ㅼ쓬</button>}</div></div>; };` }
