    codeSnippets: { react: `export const BundleCard = ({ items, discount }: { items: {name: string; price: number; selected?: boolean}[]; discount: number }) => { const [sel, setSel] = React.useState(items.map(i => i.selected ?? true)); const total = items.reduce((s, i, idx) => s + (sel[idx] ? i.price : 0), 0); const saved = Math.round(total * discount / 100); return <div className="border rounded-2xl p-5 space-y-4"><div className="flex items-center gap-2"><span className="text-xs font-bold text-orange-600 bg-orange-100 px-2 py-0.5 rounded-full">?럞 踰덈뱾 ?좎씤 {discount}%</span></div><div className="space-y-3">{items.map((item, i) => <label key={i} className="flex items-center gap-3 cursor-pointer"><input type="checkbox" checked={sel[i]} onChange={() => setSel(s => s.map((v,j) => j===i ? !v : v))} className="w-4 h-4 rounded" /><div className="flex-1"><p className="text-sm font-semibold">{item.name}</p><p className="text-xs text-gray-500">??item.price.toLocaleString()}</p></div></label>)}</div><div className="pt-3 border-t flex items-center justify-between"><div><p className="text-xs text-gray-400 line-through">??total.toLocaleString()}</p><p className="text-lg font-extrabold text-blue-600">??(total - saved).toLocaleString()}</p></div><span className="text-xs font-bold text-green-600 bg-green-50 px-3 py-1.5 rounded-xl">??saved.toLocaleString()} ?덉빟</span></div></div>; };` }
