    codeSnippets: { react: `export const MultiStepForm = ({ steps }: { steps: { title: string; fields: React.ReactNode }[] }) => { const [current, setCurrent] = React.useState(0); const isLast = current === steps.length - 1; return <div className="max-w-md mx-auto p-6 bg-white rounded-3xl border shadow-sm"><div className="flex items-center gap-2 mb-6">{steps.map((s, i) => <React.Fragment key={i}><div className={\`flex items-center gap-2 \${i <= current ? 'text-blue-600' : 'text-gray-300'}\`}><div className={\`w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold \${i < current ? 'bg-blue-600 text-white' : i === current ? 'border-2 border-blue-600' : 'border-2 border-gray-200'}\`}>{i < current ? '?? : i + 1}</div><span className="text-xs font-semibold hidden sm:block">{s.title}</span></div>{i < steps.length - 1 && <div className={\`flex-1 h-0.5 \${i < current ? 'bg-blue-600' : 'bg-gray-200'}\`} />}</React.Fragment>)}</div><div className="mb-6">{steps[current].fields}</div><div className="flex gap-3"><button onClick={() => setCurrent(c => c - 1)} disabled={current === 0} className="flex-1 py-3 border rounded-xl text-sm font-bold disabled:opacity-30">?댁쟾</button><button onClick={() => isLast ? undefined : setCurrent(c => c + 1)} className="flex-1 py-3 bg-blue-600 text-white rounded-xl text-sm font-bold">{isLast ? '?쒖텧' : '?ㅼ쓬'}</button></div></div>; };` }
