    codeSnippets: { react: `export const ValidatedField = ({ label, type = 'text', validate }: { label: string; type?: string; validate: (v: string) => string | null }) => { const [value, setValue] = React.useState(''); const [error, setError] = React.useState<string|null>(null); const [touched, setTouched] = React.useState(false); const handleBlur = () => { setTouched(true); setError(validate(value)); }; const isValid = touched && !error && value; return <div className="space-y-1.5"><label className="text-sm font-semibold text-gray-700">{label}</label><div className="relative"><input type={type} value={value} onChange={e => { setValue(e.target.value); if (touched) setError(validate(e.target.value)); }} onBlur={handleBlur} className={\`w-full px-4 py-2.5 border-2 rounded-xl text-sm outline-none transition-colors \${!touched ? 'border-gray-200 focus:border-blue-500' : error ? 'border-red-400 bg-red-50' : 'border-green-400 bg-green-50'}\`} />{isValid && <span className="absolute right-3 top-1/2 -translate-y-1/2 text-green-500 font-bold">??/span>}</div>{touched && error && <p className="text-xs text-red-500 font-medium">{error}</p>}</div>; };` }
