    codeSnippets: { react: `export const SRAnnouncement = ({ message }: { message: string }) => <div aria-live="polite" aria-atomic="true" className="sr-only">{message}</div>;\n\nexport const useSRAnnounce = () => { const [msg, setMsg] = React.useState(''); const announce = (text: string) => { setMsg(''); requestAnimationFrame(() => setMsg(text)); }; return { announcement: <SRAnnouncement message={msg} />, announce }; };` }
