    codeSnippets: { react: `export const TourTooltip = ({ step, total, title, description, position = 'bottom', onNext, onSkip }: { step: number; total: number; title: string; description: string; position?: 'top'|'bottom'|'left'|'right'; onNext: () => void; onSkip: () => void }) => { const posClass = { top: 'bottom-full mb-3', bottom: 'top-full mt-3', left: 'right-full mr-3', right: 'left-full ml-3' }[position]; return <div className={\`absolute z-50 w-72 bg-gray-900 text-white rounded-2xl p-4 shadow-2xl \${posClass}\`}><div className="flex items-center justify-between mb-2"><span className="text-xs text-gray-400">{step}/{total}</span><button onClick={onSkip} className="text-xs text-gray-400 hover:text-white">嫄대꼫?곌린</button></div><h4 className="font-bold text-sm mb-1">{title}</h4><p className="text-xs text-gray-300 leading-relaxed mb-4">{description}</p><div className="flex items-center justify-between"><div className="flex gap-1">{Array.from({length:total},(_,i) => <div key={i} className={\`w-1.5 h-1.5 rounded-full \${i<step ? 'bg-blue-500' : 'bg-gray-600'}\`} />)}</div><button onClick={onNext} className="px-4 py-1.5 bg-blue-600 text-white text-xs font-bold rounded-xl">{step === total ? '?꾨즺' : '?ㅼ쓬 ??}</button></div></div>; };` }
