    codeSnippets: { react: `export const NotificationGroup = ({ app, icon, color, notifications }: { app: string; icon: string; color: string; notifications: {id: string; title: string; body: string; time: string; read?: boolean}[] }) => { const [expanded, setExpanded] = React.useState(false); const unread = notifications.filter(n => !n.read).length; return <div className="border rounded-2xl overflow-hidden bg-white shadow-sm"><div onClick={() => setExpanded(!expanded)} className="flex items-center gap-3 px-4 py-3 cursor-pointer hover:bg-gray-50 select-none"><div style={{background:color}} className="w-9 h-9 rounded-xl flex items-center justify-center text-xl flex-shrink-0">{icon}</div><div className="flex-1 min-w-0"><div className="flex items-center gap-2"><p className="text-sm font-bold">{app}</p>{unread > 0 && <span className="text-[10px] font-bold bg-red-500 text-white px-1.5 py-0.5 rounded-full">{unread}</span>}</div><p className="text-xs text-gray-400">?뚮┝ {notifications.length}媛?/p></div><span className="text-gray-400 text-sm">{expanded ? '?? : '??}</span></div>{expanded && <div className="divide-y border-t">{notifications.map(n => <div key={n.id} className={\`px-4 py-3 \${n.read ? 'opacity-50' : ''}\`}><p className="text-sm font-semibold">{n.title}</p><p className="text-xs text-gray-500">{n.body}</p><p className="text-[10px] text-gray-400 mt-1">{n.time}</p></div>)}</div>}</div>; };` }
