    codeSnippets: { react: `export const PageTransition = ({ children, direction = 'forward', keyProp }: { children: React.ReactNode; direction?: 'forward'|'back'; keyProp: string }) => <div key={keyProp} style={{ animation: \`\${direction === 'forward' ? 'slideInRight' : 'slideInLeft'} 0.3s ease both\` }}>{children}<style>{\`@keyframes slideInRight { from { opacity: 0; transform: translateX(40px); } to { opacity: 1; transform: none; } } @keyframes slideInLeft { from { opacity: 0; transform: translateX(-40px); } to { opacity: 1; transform: none; } }\`}</style></div>;` }
